<?php require '../includes/functions.php';login_required();if($_SESSION['role']!=='student'){header('Location: ../admin/dashboard.php');exit;}$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();$t=trim($_POST['title']??'');$d=trim($_POST['description']??'');$loc=trim($_POST['location']??'');$cat=(int)($_POST['category_id']??0);$pri=$_POST['priority']??'Medium';if(!$t||!$d||!$loc||!$cat||!in_array($pri,['Low','Medium','High']))$err='Please fill all required fields.';else{$q=$pdo->prepare("INSERT INTO complaints(user_id,category_id,title,description,location,priority) VALUES(?,?,?,?,?,?)");$q->execute([$_SESSION['uid'],$cat,$t,$d,$loc,$pri]);$id=$pdo->lastInsertId();$q=$pdo->prepare("INSERT INTO complaint_updates(complaint_id,updated_by,new_status,comment) VALUES(?,?,'Pending','Complaint submitted')");$q->execute([$id,$_SESSION['uid']]);header('Location: dashboard.php');exit;}}$title='Submit Complaint';$prefix='../';require '../includes/header.php';?><section class="card form"><h1>Submit complaint</h1><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><form id="complaintForm" method="post"><input type="hidden" name="token" value="<?=e(token())?>"><div class="group"><label>Complaint title</label><input id="title" name="title" required placeholder="Classroom fan not working"></div><div class="group"><label>Category</label><select name="category_id" required><option value="">Choose category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="group"><label>College location</label><input name="location" required placeholder="Block A, Room 204"></div><div class="group"><label>Priority</label><select name="priority"><option>Low</option><option selected>Medium</option><option>High</option></select></div><div class="group"><label>Description</label><textarea id="description" name="description" required></textarea></div><button>Submit complaint</button></form></section><?php require '../includes/footer.php';?>
